css:
.mz *,.mz *::before,.mz *::after{box-sizing: border-box; margin: 0; padding: 0;}
.mz .equiv-grid{display: grid; grid-template-columns: 1fr 1fr; gap: 7px 30px;}
.mz .equiv-fila{display: flex; align-items: center; gap: 8px; font-size: 16px; font-weight: 700;}
.mz .equiv-fila .pieza{white-space: nowrap;}
.mz .equiv-fila .caja-eq{width: 52px; height: 32px; border: 1.5px solid var(--bosque); border-radius: 6px; flex-shrink: 0;}
.mz .op-tabla{border-collapse: collapse;}
.mz .op-tabla th,.mz .op-tabla td{border: 1.5px solid var(--bosque); text-align: center;}
.mz .op-tabla th{font-family: sans-serif; font-size: 12px; background: #f3f3f3; padding: 3px 0; width: 95px;}
.mz .op-tabla td{height: 34px; font-size: 19px; font-weight: 700;}
.mz .op-tabla td.op-dado{background: #f3f3f3;}
.mz .masvale-fila{display: flex; align-items: center; gap: 14px; font-size: 15px; font-weight: 600; margin-bottom: 7px; flex-wrap: wrap;}
.mz .masvale-fila .pista{min-width: 150px;}
.mz .masvale-fila .op{border: 1.5px solid var(--bosque); border-radius: 8px; padding: 5px 16px; font-size: 20px; font-weight: 700;}
.mz .pos-fila{display: flex; align-items: center; gap: 10px; font-size: 15px; font-weight: 600; margin-bottom: 7px; flex-wrap: wrap;}
.mz .pos-fila .num-marcado{font-size: 22px; font-weight: 700; letter-spacing: 2px;}
.mz .pos-fila .num-marcado .destacado{text-decoration: underline; text-underline-offset: 3px;}
.mz .pos-fila .caja-pos{width: 130px; height: 34px; border: 1.5px solid var(--bosque); border-radius: 6px;}
